nextflow_process {

    name "Test Process PARABRICKS_RNAFQ2BAM"
    script "../main.nf"
    process "PARABRICKS_RNAFQ2BAM"

    tag "gpu_highmem"
    tag "modules"
    tag "modules_nfcore"
    tag "parabricks"
    tag "parabricks/rnafq2bam"
    tag "star/genomegenerate"

    setup {

        run("STAR_GENOMEGENERATE") {
            script "../../../star/genomegenerate/main.nf"
            process {
                """
                input[0] = [
                    [ id:'minigenome_fasta' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/minigenome.fa')
                ]
                input[1] = [
                    [ id:'minigenome_gtf' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/minigenome.gtf')
                ]
                """
            }
        }
    }

    config "./nextflow.config"

    test("homo_sapiens") {

        when {
            params {
                module_args = '--num-streams-per-gpu 1 --read-files-command zcat --x3'
            }
            process {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:true ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/test_starfusion_rnaseq_1.fastq.gz', checkIfExists: true) ]
                ])
                input[1] = Channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = STAR_GENOMEGENERATE.out.index
                input[3] = false
                input[4] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert file(process.out.log_final[0][1]).text.contains('Uniquely mapped reads %') },
                { assert snapshot(
                    file(process.out.log_final[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith('versions') },
                    bam(process.out.bam[0][1]).getReadsMD5()
                ).match() }
            )
        }
    }

    test("homo_sapiens - stub") {

        options "-stub"

        when {
            params {
                module_args = ''
            }
            process {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:true ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/test_starfusion_rnaseq_1.fastq.gz', checkIfExists: true) ]
                ])
                input[1] = Channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/minigenome.fa', checkIfExists: true)
                ])
                input[2] = STAR_GENOMEGENERATE.out.index
                input[3] = false
                input[4] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

    test("homo_sapiens - paired_end - multiple_fastq") {

        when {
            params {
                module_args = '--num-streams-per-gpu 1 --read-files-command zcat --x3'
            }
            process {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/test_starfusion_rnaseq_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/test_starfusion_rnaseq_2.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                input[1] = Channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = STAR_GENOMEGENERATE.out.index
                input[3] = false
                input[4] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert file(process.out.log_final[0][1]).text.contains('Uniquely mapped reads %') },
                { assert snapshot(
                    file(process.out.log_final[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith('versions') },
                    bam(process.out.bam[0][1]).getReadsMD5()
                ).match() }
            )
        }
    }

    test("homo_sapiens_chimeric") {

        when {
            params {
                module_args = '--num-streams-per-gpu 1 --read-files-command zcat --out-chim-type Junctions --min-chim-segment 15 --x3'
            }
            process {
                """
                 input[0] = Channel.of([
                    [ id:'test', single_end:true ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/test_starfusion_rnaseq_1.fastq.gz', checkIfExists: true) ]
                ])
                input[1] = Channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = STAR_GENOMEGENERATE.out.index
                input[3] = false
                input[4] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert file(process.out.log_final[0][1]).text.contains('Uniquely mapped reads %') },
                { assert snapshot(
                    bam(process.out.bam[0][1]).getReadsMD5(),
                    file(process.out.bai[0][1]).name,
                    file(process.out.junction[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("homo_sapiens_chimeric - stub") {

        options "-stub"

        when {
            params {
                module_args = '--out-chim-type Junctions'
            }
            process {
                """
                 input[0] = Channel.of([
                    [ id:'test', single_end:true ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/test_starfusion_rnaseq_1.fastq.gz', checkIfExists: true) ]
                ])
                input[1] = Channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = STAR_GENOMEGENERATE.out.index
                input[3] = false
                input[4] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

}

